script.setup:
// d3-force runs the simulation (collision, centering, group pulls); the scene ticks it
// once per frame and draws every node as a shaded disc. The pointer pushes nodes away.
const d3 = await ctx.utils.import("https://esm.sh/d3-force@3.0.0");
const N = 900, GROUPS = 5;
const nodes = Array.from({ length: N }, (_, i) => {
  const a = Math.random() * Math.PI * 2, d = Math.sqrt(Math.random()) * 420;
  return { x: Math.cos(a) * d, y: Math.sin(a) * d, r: 5 + Math.pow(Math.random(), 3) * 26, group: i % GROUPS };
});
// The pointer is a node of its own: fixed (fx/fy) where the pointer is, far away until it moves.
const pointer = { x: 1e5, y: 1e5, fx: 1e5, fy: 1e5, r: 0, group: -1 };
const sim = d3.forceSimulation([...nodes, pointer])
  .alphaDecay(0.01).alphaTarget(0.05).velocityDecay(0.3)
  .force("collide", d3.forceCollide((n) => n.r + 1.5).strength(0.9).iterations(2))
  .force("x", d3.forceX(0).strength(0.03))
  .force("y", d3.forceY(0).strength(0.03))
  .force("radial", null)
  .stop();
const gl = ctx.gl;
const vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 16, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 16, 8);
gl.bindVertexArray(null);
const program = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec2 a_info;
uniform vec2 u_scale; uniform float u_px; out float v_group; out float v_r;
void main(){
  v_group = a_info.y; v_r = a_info.x;
  gl_Position = vec4(a_position * u_scale, 0.0, 1.0);
  gl_PointSize = a_info.x * 2.0 * u_px;
}`, `#version 300 es
precision highp float; in float v_group; in float v_r; out vec4 outColor;
uniform vec3 u_palette[5];
void main(){
  vec2 p = gl_PointCoord * 2.0 - 1.0; p.y = -p.y;
  float d = length(p); if (d > 1.0) discard;
  vec3 c = u_palette[int(v_group + 0.5)];
  // A soft sphere lit from the top left, with a darker rim.
  vec3 n = vec3(p, sqrt(max(0.0, 1.0 - d * d)));
  float light = 0.35 + 0.65 * max(dot(n, normalize(vec3(-0.5, 0.6, 0.8))), 0.0);
  float spec = pow(max(dot(reflect(-normalize(vec3(-0.5, 0.6, 0.8)), n), vec3(0, 0, 1)), 0.0), 24.0);
  vec3 col = c * light + spec * 0.35;
  col *= smoothstep(1.0, 0.86, d) * 0.4 + 0.6;
  outColor = vec4(col, smoothstep(1.0, 0.93, d));
}`);
Object.assign(ctx.state, { d3, sim, nodes, pointer, N, GROUPS, vao, buffer, program, data: new Float32Array(N * 4), layout: -1, moved: false });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, d3 = s.d3;
const [w, h] = ctx.resolution, H = 1150, W = H * w / h;
// Switching the layout swaps the forces and reheats the simulation.
if (u.u_layout !== s.layout || u.u_shake) {
  s.layout = u.u_layout;
  const ring = 300, centers = Array.from({ length: s.GROUPS }, (_, g) => [Math.cos(g / s.GROUPS * 6.283 + 0.6) * ring * 1.15, Math.sin(g / s.GROUPS * 6.283 + 0.6) * ring]);
  const byGroup = s.layout === 1;
  s.sim.force("x", d3.forceX((n) => byGroup && n.group >= 0 ? centers[n.group][0] : 0).strength(s.layout === 2 ? 0.005 : 0.035));
  s.sim.force("y", d3.forceY((n) => byGroup && n.group >= 0 ? centers[n.group][1] : 0).strength(s.layout === 2 ? 0.005 : 0.035));
  s.sim.force("radial", s.layout === 2 ? d3.forceRadial((n) => 120 + n.group * 70, 0, 0).strength(0.08) : null);
  if (u.u_shake) for (const n of s.nodes) { n.vx += (Math.random() - 0.5) * 60; n.vy += (Math.random() - 0.5) * 60; }
  s.sim.alpha(0.6);
}
s.sim.force("collide").strength(u.u_stiffness);
// The pointer acts only after it has moved away from the default center.
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
const p = s.pointer;
if (s.moved) {
  p.fx = (ctx.mouse[0] - 0.5) * W; p.fy = (0.5 - ctx.mouse[1]) * H;
  p.r = u.u_push * (ctx.mouseDown ? 2.2 : 1);
}
s.sim.tick();
s.nodes.forEach((n, i) => s.data.set([n.x, n.y, n.r, n.group], i * 4));
gl.clearColor(0.035, 0.037, 0.05, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
gl.useProgram(s.program);
ctx.utils.setUniforms(s.program, { u_scale: [2 / W, 2 / H], u_px: h / H, u_palette: [u.u_color1, u.u_color2, u.u_color3, u.u_color4, u.u_color5].flat() });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, s.data, gl.DYNAMIC_DRAW);
gl.drawArrays(gl.POINTS, 0, s.N);
gl.bindVertexArray(null); gl.disable(gl.BLEND);
ctx.publish("alpha", +s.sim.alpha().toFixed(3));
